mysql_profile {
  hostname = var.source_mysql.hostname
  port     = var.source_mysql.port
  username = var.source_mysql.username
  password = var.source_mysql.password

  dynamic "ssl_config" {
    for_each = var.source_mysql.ssl == null ? [] : [var.source_mysql.ssl]

    content {
      ca_certificate     = ssl_config.value.ca_certificate
      client_certificate = ssl_config.value.client_certificate
      client_key         = ssl_config.value.client_key
    }
  }
}

data "google_bigquery_default_service_account" "datastream" {}

resource "google_kms_crypto_key_iam_member" "bigquery_service_agent" {
  crypto_key_id = google_kms_crypto_key.datastream.id
  role          = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
  member        = "serviceAccount:${data.google_bigquery_default_service_account.datastream.email}"
}
